// Older catch-all rows ("Fujian & Zhejiang air bases", "Moscow-region air bases") stood in for
// many airfields at once. Where a country now has its air and naval bases listed one by one, those
// catch-alls keep only a quarter of their aircraft and ships, so the units sit at the real bases.
const CATCHALL = /\b(air ?bases|airfields|naval bases|bases)\b/i;
Object.entries(window.DEPLOYMENTS_DETAIL).forEach(([iso, rows]) => {
  const old = window.DEPLOYMENTS[iso] || [];
  if (rows.filter(r => r[4] > 0 || r[5] > 0).length >= 5) old.forEach(r => { if (!r[7] && CATCHALL.test(r[0])) { r[4] *= 0.25; r[5] *= 0.25; } });
  window.DEPLOYMENTS[iso] = old.concat(rows);
});
